static FontView fontViewFor(MnemosFontRole role) {
    switch (role) {
        case MnemosFontRole::Meta14:
            return {GLYPHS_Meta14, BITMAP_Meta14, GLYPH_COUNT_Meta14, GLYPHS_FALLBACK_14, BITMAP_FALLBACK_14, GLYPH_COUNT_FALLBACK_14};
        case MnemosFontRole::Body18:
            return {GLYPHS_Body18, BITMAP_Body18, GLYPH_COUNT_Body18, GLYPHS_FALLBACK_18, BITMAP_FALLBACK_18, GLYPH_COUNT_FALLBACK_18};
        case MnemosFontRole::Title22:
            return {GLYPHS_Title22, BITMAP_Title22, GLYPH_COUNT_Title22, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Eyebrow:
            return {GLYPHS_Eyebrow, BITMAP_Eyebrow, GLYPH_COUNT_Eyebrow, GLYPHS_FALLBACK_14, BITMAP_FALLBACK_14, GLYPH_COUNT_FALLBACK_14};
        case MnemosFontRole::Small:
            return {GLYPHS_Small, BITMAP_Small, GLYPH_COUNT_Small, GLYPHS_FALLBACK_14, BITMAP_FALLBACK_14, GLYPH_COUNT_FALLBACK_14};
        case MnemosFontRole::Body:
            return {GLYPHS_Body, BITMAP_Body, GLYPH_COUNT_Body, GLYPHS_FALLBACK_18, BITMAP_FALLBACK_18, GLYPH_COUNT_FALLBACK_18};
        case MnemosFontRole::Strong:
            return {GLYPHS_Strong, BITMAP_Strong, GLYPH_COUNT_Strong, GLYPHS_FALLBACK_18, BITMAP_FALLBACK_18, GLYPH_COUNT_FALLBACK_18};
        case MnemosFontRole::Heading:
            return {GLYPHS_Heading, BITMAP_Heading, GLYPH_COUNT_Heading, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Title:
            return {GLYPHS_Title, BITMAP_Title, GLYPH_COUNT_Title, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Figure:
            return {GLYPHS_Figure, BITMAP_Figure, GLYPH_COUNT_Figure, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Display:
            return {GLYPHS_Display, BITMAP_Display, GLYPH_COUNT_Display, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Card:
            return {GLYPHS_Card, BITMAP_Card, GLYPH_COUNT_Card, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::CardSmall:
            return {GLYPHS_CardSmall, BITMAP_CardSmall, GLYPH_COUNT_CardSmall, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        case MnemosFontRole::Hanzi:
            return {GLYPHS_Hanzi, BITMAP_Hanzi, GLYPH_COUNT_Hanzi, GLYPHS_FALLBACK_22, BITMAP_FALLBACK_22, GLYPH_COUNT_FALLBACK_22};
        default:
            return fontViewFor(MnemosFontRole::Body18);
    }
}
